/-- Send a valid labelled representation to its extensional law.  For the ambient setting, [the defined object](goal) is given by [its defining clause](step:1). -/
def ofProbabilityLaw {k : ℕ} {radius : ℝ} (ν : ProbabilityLaw k radius) :
    LawModulo k radius := Quotient.mk _ ν

/-- The labelled representation of the unit point mass at zero.  For the ambient setting, [the defined object](goal) is given by [its defining clause](step:1). -/
def deltaZero {k : ℕ} {radius : ℝ} : AtomicLaw k radius :=
  { weight := fun i => if i.val = 0 then 1 else 0
    atom := fun _ => 0 }

/-- Distance from a point to a finite set.     For [the supplied parameters](hyp:x,C), [the defined object](goal) is given by [its defining clause](step:1). -/
noncomputable def distToFinset (x : ℝ) (C : Finset ℝ) : ℝ :=
  sInf {d : ℝ | ∃ y ∈ C, d = |x - y|}

/-- One-Wasserstein distance, definitionally the infimum over the finite transport polytope.
    @realizes \(W_1\)(infimum of finite transport costs)  For the ambient setting, [the defined object](goal) is given by [its defining clause](step:1). -/
noncomputable def wass1 {k : ℕ} {radius : ℝ} (ν ξ : AtomicLaw k radius) : ℝ :=
  sInf {c : ℝ | ∃ γ : TransportPlan ν ξ, transportCost γ = c}

/-- Integer coordinates large enough to encode a mesh-`1/H` scalar bounded by `B`. -/
abbrev BoundedLatticeInt (H : ℕ) (B : ℝ) :=
  {z : ℤ // z ∈ Finset.Icc (-⌈(H : ℝ) * B⌉ : ℤ) ⌈(H : ℝ) * B⌉}

/-- For the ambient setting, [Bounded Outcome Proxy Product](goal) is given by [its defining clause](step:1). -/
def BoundedOutcomeProxyProduct : Prop :=
  ∀ᵐ w ∂P, ‖matrixCLM (w.Y • outerProduct w.Z w.X)‖ ≤ L

/-- For the ambient setting, [Bounded Proxy Product](goal) is given by [its defining clause](step:1). -/
def BoundedProxyProduct : Prop :=
  ∀ᵐ w ∂P, ‖matrixCLM (outerProduct w.Z w.X)‖ ≤ L

/-- For the ambient setting, [Bounded Target Proxy](goal) is given by [its defining clause](step:1). -/
def BoundedTargetProxy : Prop :=
  ∀ᵐ w ∂P, Real.sqrt (∑ i, (w.X i) ^ 2) ≤ L

/-- Domain of the simultaneous-concentration constant.     For [the supplied parameters](hyp:C0), [the defined object](goal) is given by [its defining clause](step:1). -/
def ConcentrationConstantDomain (C0 : ℝ) : Prop :=
  1 ≤ C0 -- @realizes \(C_0\)(concentration constant at least one)

/-- For the ambient setting, [Distinct Effects](goal) is given by [its defining clause](step:1). -/
def DistinctEffects : Prop :=
  ((Finset.univ.filter fun u => 0 < latentMass P u).image (latentEffect P)).card = k

/-- For [the supplied parameters](hyp:w), [to Coordinates](goal) is given by [its defining clause](step:1). -/
def FullData.toCoordinates {k dx dz : ℕ} (w : FullData k dx dz) :=
  (w.U, w.T, w.X, w.Z, w.Y0, w.Y1, w.Y)

/-- Homogeneity at a common latent effect.
    @realizes \(\tau_\star\)(common value of all latent effects)        For [the supplied parameters](hyp:P,tauStar), [the defined object](goal) is given by [its defining clause](step:1). -/
def HomogeneousEffects {k dx dz : ℕ} (P : Measure (FullData k dx dz))
    (tauStar : ℝ) : Prop := ∀ u, latentEffect P u = tauStar

/-- Probability-simplex constraint for labelled weight vectors.     For [the supplied parameters](hyp:p), [the defined object](goal) is given by [its defining clause](step:1). -/
def InSimplex {k : ℕ} (p : Fin k → ℝ) : Prop :=
  (∀ i, 0 ≤ p i) ∧ ∑ i, p i = 1

/-- Range of the universal local-experiment radius.     For [the supplied parameters](hyp:cLoc), [the defined object](goal) is given by [its defining clause](step:1). -/
def LocalRadiusDomain (cLoc : ℝ) : Prop :=
  0 < cLoc ∧ cLoc < 1 -- @realizes \(c_{\mathrm{loc}}\)(cLoc in (0,1))

/-- For [the supplied parameters](hyp:D,z,v), [Matrix Eigenvector](goal) is given by [its defining clause](step:1). -/
def MatrixEigenvector {k : ℕ} (D : RectMatrix k k) (z : ℂ) (v : Fin k → ℂ) : Prop :=
  v ≠ 0 ∧ ∀ i, ∑ j, (D i j : ℂ) * v j = z * v i

/-- For [the supplied parameters](hyp:cost), [total](goal) is given by [its defining clause](step:1). -/
def NetOperationCount.total (cost : NetOperationCount) : ℕ :=
  cost.arithmetic + cost.comparison + cost.singularValue + cost.rootIsolation

/-- The qualitative simple-effect separation condition used by the published recovery regime.     For [the supplied parameters](hyp:tau), [the defined object](goal) is given by [its defining clause](step:1). -/
def PublishedSpectralSeparation {k : ℕ} (tau : Fin k → ℝ) : Prop :=
  ∀ u v, u ≠ v → tau u ≠ tau v

/-- Coordinate keys which are realized by at least one well-formed lattice point.  Passing to
keys removes harmless duplicate grid bases having the same prescribed visible coordinates.        For [the supplied parameters](hyp:k,dx,dz,n,L,pi0,sigma0), [the defined object](goal) is given by [its defining clause](step:1). -/
def StructuredLatticeKey (k dx dz n : ℕ) (L pi0 sigma0 : ℝ) :=
  {key : List ℝ // ∃ θ : StructuredLatticePoint k dx (effectRadius dz L sigma0),
    θ.WellFormed (dz := dz) (n := n) (L := L) (pi0 := pi0) (sigma0 := sigma0) ∧
      structuredLatticeLexKey θ = key}

/-- For [the supplied parameters](hyp:s,q), [Summary Lex LE](goal) is given by [its defining clause](step:1). -/
def SummaryLexLE {dx dz : ℕ} (s q : SummarySpace dx dz) : Prop :=
  summaryLexKey s = summaryLexKey q ∨ List.Lex (· < ·) (summaryLexKey s) (summaryLexKey q)

/-- For [the supplied parameters](hyp:s), [to Coordinates](goal) is given by [its defining clause](step:1). -/
def SummarySpace.toCoordinates {dx dz : ℕ} (s : SummarySpace dx dz) :
    SummaryCoordinates dx dz := (s.M0, s.M1, s.N0, s.N1, s.mX)

/-- Exact domain of the generic tangent amplitude used by the labelled path.     For [the supplied parameters](hyp:h), [the defined object](goal) is given by [its defining clause](step:1). -/
def TangentAmplitudeDomain (h : ℝ) : Prop :=
  h ∈ Set.Icc (-1 : ℝ) 1 -- @realizes \(h\)(h in [-1,1])

/-- A real-valued function with a finite uniform envelope.     For [the supplied parameters](hyp:f), [the defined object](goal) is given by [its defining clause](step:1). -/
def UniformlyBounded {α : Type*} (f : α → ℝ) : Prop :=
  ∃ B : ℝ, ∀ x, |f x| ≤ B

/-- The positive-dimensional domain on which the cited VMW model and recovery statements apply.     For [the supplied parameters](hyp:k,dx,dz), [the defined object](goal) is given by [its defining clause](step:1). -/
def VMWPositiveDimensionDomain (k dx dz : ℕ) : Prop :=
  0 < k ∧ k ≤ dx ∧ k ≤ dz

/-- Admissible summary image. @realizes \(\mathscr S\)(S(M))     For [the supplied parameters](hyp:k,dx,dz,L,pi0,sigma0), [the defined object](goal) is given by [its defining clause](step:1). -/
def admissibleImage (k dx dz : ℕ) (L pi0 sigma0 : ℝ) : Set (SummarySpace dx dz) :=
  {s | ∃ Q : ModelLaw k dx dz L pi0 sigma0, Q.summary = s}

/-- For [the supplied parameters](hyp:t,sample), [arm Count](goal) is given by [its defining clause](step:1). -/
def armCount {n dx dz : ℕ} (t : Bool) (sample : Fin n → Obs dx dz) : ℕ :=
  (Finset.univ.filter fun i => (sample i).T = t).card

/-- For [the supplied parameters](hyp:D), [complexify Matrix](goal) is given by [its defining clause](step:1). -/
def complexifyMatrix {k : ℕ} (D : RectMatrix k k) : Matrix (Fin k) (Fin k) ℂ :=
  fun i j => (D i j : ℂ)

/-- Smallest positive pairwise effect gap, with `⊤` for a singleton support.
    @realizes \(\delta(P)\)(nearest positive effect gap)  For the ambient setting, [the defined object](goal) is given by [its defining clause](step:1). -/
noncomputable def effectGap : EReal :=
  sInf {d : EReal | ∃ u v : Fin k,
    0 < latentMass P u ∧ 0 < latentMass P v ∧ latentEffect P u ≠ latentEffect P v ∧
    d = |latentEffect P u - latentEffect P v|}

