/-- Observed iid experiment. @realizes \(\mathcal E_n\)(set of model product laws)     For [the supplied parameters](hyp:n), [the defined object](goal) is given by [its defining clause](step:1). -/
def sampleExperiment (n : ℕ) : Set (Measure (Fin n → Obs dx dz)) :=
  {Q | ∃ (P : Measure (FullData k dx dz)) (hP : IsProbabilityMeasure P),
    letI := hP
    Nonempty (UCVMWModel (L := L) (pi0 := pi0) (sigma0 := sigma0) P) ∧
      Q = sampleLaw (n := n) P}

/-- Closed feasible-summary space. @realizes \(\mathcal K\)(closure of admissible image)     For [the supplied parameters](hyp:k,dx,dz,L,pi0,sigma0), [the defined object](goal) is given by [its defining clause](step:1). -/
def summaryClosure (k dx dz : ℕ) (L pi0 sigma0 : ℝ) : Set (SummarySpace dx dz) :=
  closure (admissibleImage k dx dz L pi0 sigma0)

/-- The entrywise closed cube of rectangular matrices.     For [the supplied parameters](hyp:rows,cols,L), [the defined object](goal) is given by [its defining clause](step:1). -/
-- @node: summaryMatrixBox
def summaryMatrixBox (rows cols : ℕ) (L : ℝ) : Set (RectMatrix rows cols) :=
  {A | ∀ i j, A i j ∈ Icc (-L) L}

/-- The coordinatewise closed cube for the unconditional proxy mean.     For [the supplied parameters](hyp:d,L), [the defined object](goal) is given by [its defining clause](step:1). -/
-- @node: summaryVectorBox
def summaryVectorBox (d : ℕ) (L : ℝ) : Set (Fin d → ℝ) :=
  {x | ∀ i, x i ∈ Icc (-L) L}

/-- The retained sharp summary-inversion image, independent of the computable outer set.     For [the supplied parameters](hyp:R,sample,alpha,C0), [the defined object](goal) is given by [its defining clause](step:1). -/
noncomputable def theoreticalConfidenceSet {k dx dz n : ℕ} {L pi0 sigma0 : ℝ}
    (R : SummaryRepairData k dx dz n L pi0 sigma0)
    (sample : Fin n → Obs dx dz) (alpha C0 : ℝ) :
    Set (AtomicLaw.LawModulo k (effectRadius dz L sigma0)) :=
  let r := summaryRadius n alpha C0 L
  if summaryClosure k dx dz L pi0 sigma0 = ∅ then
    {AtomicLaw.LawModulo.deltaZeroLaw R.k_pos R.radius_nonneg}
  else {ν | ∃ q : {q // q ∈ summaryClosure k dx dz L pi0 sigma0},
    dS q.1 (R.Pi (empSummary sample)) ≤ 2 * r ∧ ν = R.Fbar q}

/-- For [the supplied parameters](hyp:C), [wass Diameter](goal) is given by [its defining clause](step:1). -/
noncomputable def wassDiameter {k : ℕ} {radius : ℝ}
    (C : Set (AtomicLaw.LawModulo k radius)) : ℝ :=
  sSup {d | ∃ x ∈ C, ∃ y ∈ C, d = AtomicLaw.LawModulo.wass1 x y}

